import json
m=json.load(open('counter.model.json'))
def ev(e,s,a):
    op=e['op']
    if op=='constant': return e['value']
    if op=='state': return s[e['field']]
    if op=='parameter': return a[e['name']]
    if op=='add': return (ev(e['left'],s,a)+ev(e['right'],s,a))%16
    if op=='sub': return (ev(e['left'],s,a)-ev(e['right'],s,a))%16
    if op=='if': return ev(e['then'],s,a) if ev(e['condition'],s,a) else ev(e['else'],s,a)
    raise ValueError(op)
def pred(e,s,out):
    op=e['op']
    if op=='true': return True
    if op=='false': return False
    if op=='equal': return ev(e['left'],s,None) if False else None
def wev(e,s,a,out):
    op=e['op']
    if op=='constant': return e['value']
    if op=='state': return s[e['field']]
    if op=='parameter': return a[e['name']]
    if op=='output': return out[e['field']]
    if op=='add': return (wev(e['left'],s,a,out)+wev(e['right'],s,a,out))%16
    if op=='sub': return (wev(e['left'],s,a,out)-wev(e['right'],s,a,out))%16
    if op=='if': return wev(e['then'],s,a,out) if wcond(e['condition'],s,a,out) else wev(e['else'],s,a,out)
def wcond(e,s,a,out):
    op=e['op']
    if op=='true': return True
    if op=='false': return False
    if op=='equal': return wev(e['left'],s,a,out)==wev(e['right'],s,a,out)
    if op=='less': return wev(e['left'],s,a,out)<wev(e['right'],s,a,out)
    if op=='less_equal': return wev(e['left'],s,a,out)<=wev(e['right'],s,a,out)
    if op=='not': return not wcond(e['argument'],s,a,out)
    if op=='and': return wcond(e['left'],s,a,out) and wcond(e['right'],s,a,out)
    if op=='or': return wcond(e['left'],s,a,out) or wcond(e['right'],s,a,out)
    raise ValueError(op)
c=json.load(open('requirements.contract.json'))
t=m['transition']
fails=0; checked=0
for v in range(16):
    for amt in range(16):
        s={'value':v}; a={'amount':amt}
        out={'value':wev(t['value'],s,a,None)}
        for p in c['properties']:
            checked+=1
            if not wcond(p['statement'],s,a,out):
                fails+=1
                if fails<5: print('FAIL',p['name'],v,amt,out)
        # also check intended spec: value+amount if fits in 0..15 else value
        exp = (v+amt) if (v+amt)<=15 else v
        if out['value']!=exp:
            print('SPEC MISMATCH',v,amt,out['value'],exp)
print('assignments:',16*16,'property checks:',checked,'failures:',fails)
